'use strict';

const express = require('express');
const compression = require('compression');

const app = express();
const PORT = process.env.PORT || 3000;

// Enable gzip (and deflate) compression via the compression middleware.
// It compresses responses when the client sends Accept-Encoding: gzip,
// and skips compression for `identity` requests.
app.use(compression());

// GET /big -> ~50KB JSON array of generated objects
app.get('/big', (_req, res) => {
  const items = [];
  const N = 300;
  for (let i = 0; i < N; i++) {
    items.push({
      id: i,
      name: `item-${i}-${'x'.repeat(40)}`,
      description: `Generated payload entry number ${i} with some filler text to reach the target size. `.repeat(2),
      tags: ['alpha', 'beta', 'gamma', i % 7],
      active: i % 2 === 0,
      score: Math.round(Math.sin(i) * 10000) / 10000,
    });
  }
  res.json(items);
});

app.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});

